package com.monitoring.proxyapi.domain.model;

import java.time.Instant;
import java.util.Objects;

/**
 * Immutable audit record produced by the logging proxy for every single invocation, successful or not.
 *
 * @param requestId         unique correlation id (UUID) generated by the proxy
 * @param serviceId         service that received the call
 * @param operation         operation name as requested by the client
 * @param durationMs        wall-clock time spent inside the proxy, including the real service
 * @param status            {@link CallStatus#SUCCESS} or {@link CallStatus#ERROR}
 * @param timestamp         instant at which the proxy intercepted the call
 * @param inputParams       JSON with the input parameters (sensitive fields already masked)
 * @param responsePayload   JSON with the full response, or the error description when the call failed
 * @param stackTraceSummary condensed stack trace for failed calls, {@code null} on success
 * @param cacheHit          whether the response was served by the proxy cache without touching the real service
 */
public record AuditLogEntry(
        String requestId,
        ServiceId serviceId,
        String operation,
        long durationMs,
        CallStatus status,
        Instant timestamp,
        String inputParams,
        String responsePayload,
        String stackTraceSummary,
        boolean cacheHit) {

    public AuditLogEntry {
        Objects.requireNonNull(requestId, "requestId");
        Objects.requireNonNull(serviceId, "serviceId");
        Objects.requireNonNull(operation, "operation");
        Objects.requireNonNull(status, "status");
        Objects.requireNonNull(timestamp, "timestamp");
    }

    public boolean failed() {
        return status == CallStatus.ERROR;
    }
}
